// Build the fivem-client alt:V resource from this server's FiveM resources.
//
//   node tools/build-client-bundle.mjs [--out DIR] [--resdir DIR] [--esbuild CMD]
//
// Pipeline (the same one the test harness exercises end-to-end):
//   1. boot the real cfx-compat server runtime headless (mock adapter)
//   2. load every real resource dir under fivem_resources/
//   3. runtime.buildClientPayload() -> transformed client/shared scripts,
//      ui_page + files per resource
//   4. emit:
//      client/gen/payload.gen.js    (PAYLOAD as an ES module)
//      client/gen/prelude.gen.js    (client-prelude.lua as a JS string)
//      OUT/resource.toml            (alt:V resource manifest)
//      OUT/client.js                (esbuild bundle of client/boot.entry.js;
//                                    alt-client + natives stay external)
//      OUT/ui/<res>/<page>          (ui_page html copies with the NUI compat
//                                    shim injected, so FiveM NUI pages work
//                                    unmodified inside alt:V webviews)
import { CfxCompatRuntime } from '../cfx/runtime.js';
import { makeMockAlt } from '../test/mock-alt.js';
import { nuiCompatScriptFor } from '../client/core.mjs';
import * as fs from 'fs';
import * as path from 'path';
import { fileURLToPath } from 'url';
import { execFileSync } from 'child_process';

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const ROOT = path.join(__dirname, '..');

function arg(name, dflt) {
  const i = process.argv.indexOf(name);
  return i >= 0 ? process.argv[i + 1] : dflt;
}

const OUT = path.resolve(arg('--out', path.join(ROOT, '..', 'fivem-client')));
// Default to the DEPLOYED FiveM resources (server/fivem_resources — includes
// [core]/es_extended etc.). The in-repo fixtures under fivem-compat/fivem_resources
// are only a fallback: building from them once shipped a client bundle with no
// es_extended in it, which meant players got free-roam with no ESX client.
const DEPLOYED = path.join(ROOT, '..', '..', 'fivem_resources');
const RESDIR = path.resolve(arg('--resdir',
  fs.existsSync(path.join(DEPLOYED, '[core]')) ? DEPLOYED : path.join(ROOT, 'fivem_resources')));
const ESBUILD = arg('--esbuild', 'npx --yes esbuild@0.28.2');

const mock = makeMockAlt();
const rt = new CfxCompatRuntime(mock);
await rt.init();

const loaded = [];
// category-aware discovery — same semantics as listResourceDirs() in index.js:
// [core]/name, [standalone]/name, or a direct resource dir
const found = [];
for (const entry of fs.readdirSync(RESDIR, { withFileTypes: true })) {
  if (!entry.isDirectory() || entry.name.startsWith('__tmp') || entry.name.startsWith('.')) continue;
  if (entry.name.startsWith('[')) {
    for (const e2 of fs.readdirSync(path.join(RESDIR, entry.name), { withFileTypes: true })) {
      const d = path.join(RESDIR, entry.name, e2.name);
      if (e2.isDirectory() && fs.existsSync(path.join(d, 'fxmanifest.lua'))) found.push([e2.name, d]);
    }
  } else if (fs.existsSync(path.join(RESDIR, entry.name, 'fxmanifest.lua'))) {
    found.push([entry.name, path.join(RESDIR, entry.name)]);
  }
}
// loadAll = dependency-ordered loading (manifest `dependencies` + @imports).
// Loading alphabetically here once broke es_extended: it loads before esx_lib,
// its '@esx_lib/imports.lua' import fails, the resource is marked FAILED and
// silently drops out of the client payload — players then get free-roam with
// no ESX client code at all.
const ordered = await rt.loadAll(found);
loaded.push(...ordered.filter((r) => r.status === 'running').map((r) => r.name));

const payload = rt.buildClientPayload();
console.log(`[build-client] loaded ${loaded.length} resource(s): ${loaded.join(', ')}`);
console.log(`[build-client] payload: ${payload.resources.length} running resource(s), ` +
  `${payload.resources.reduce((n, r) => n + (r.scripts || []).length, 0)} client script(s)`);

// ---- generated code modules ----
const genDir = path.join(ROOT, 'client', 'gen');
fs.mkdirSync(genDir, { recursive: true });
fs.writeFileSync(path.join(genDir, 'payload.gen.js'),
  '// AUTO-GENERATED by tools/build-client-bundle.mjs — do not edit.\n' +
  `export const PAYLOAD = ${JSON.stringify(payload, null, 1)};\n`);
const preludeSrc = fs.readFileSync(path.join(ROOT, 'client', 'client-prelude.lua'), 'utf8');
fs.writeFileSync(path.join(genDir, 'prelude.gen.js'),
  '// AUTO-GENERATED by tools/build-client-bundle.mjs — do not edit.\n' +
  `export const PRELUDE_SRC = ${JSON.stringify(preludeSrc)};\n`);

// ---- output resource ----
fs.mkdirSync(OUT, { recursive: true });
const clientFiles = ['client.js'];

for (const res of payload.resources) {
  if (!res.uiPage) continue;
  // resources may live in [category] subfolders — use the real dir
  const resDir = (rt.engines.get(res.name) || {}).dir || path.join(RESDIR, res.name);
  const src = path.join(resDir, res.uiPage);
  if (!fs.existsSync(src)) {
    console.error(`[build-client] WARN: ${res.name}: ui_page '${res.uiPage}' not found — skipped`);
    continue;
  }
  const dstDir = path.join(OUT, 'ui', res.name);
  fs.mkdirSync(dstDir, { recursive: true });
  let html = fs.readFileSync(src, 'utf8');
  // inject the NUI compat shim as early as possible in <head>
  const shim = nuiCompatScriptFor(res.name);
  if (/<head[^>]*>/i.test(html)) {
    html = html.replace(/<head[^>]*>/i, (m) => m + shim);
  } else {
    html = shim + html;
  }
  const base = path.basename(res.uiPage);
  fs.writeFileSync(path.join(dstDir, base), html);
  clientFiles.push(`ui/${res.name}/${base}`);
  // sibling files referenced relatively (css/js assets next to the page)
  for (const f of res.files || []) {
    const rel = String(f).replace(/\\/g, '/');
    if (rel === res.uiPage || path.dirname(rel) !== path.dirname(res.uiPage)) continue;
    const fsrc = path.join(RESDIR, res.name, rel);
    if (fs.existsSync(fsrc)) {
      fs.copyFileSync(fsrc, path.join(dstDir, path.basename(rel)));
      clientFiles.push(`ui/${res.name}/${path.basename(rel)}`);
    }
  }
}

fs.writeFileSync(path.join(OUT, 'resource.toml'),
  `# AUTO-GENERATED by tools/build-client-bundle.mjs — do not edit.\n` +
  `type = 'js'\n` +
  `client-main = 'client.js'\n` +
  `client-files = [\n${clientFiles.map((f) => `    '${f}'`).join(',\n')}\n]\n`);

// ---- bundle ----
const entry = path.join(ROOT, 'client', 'boot.entry.js');
const outfile = path.join(OUT, 'client.js');
const cmd = `${ESBUILD} ${JSON.stringify(entry)} --bundle --format=esm --external:alt-client --external:natives --outfile=${JSON.stringify(outfile)}`;
console.log(`[build-client] ${cmd}`);
execFileSync(cmd, { shell: true, stdio: 'inherit' });

const size = fs.statSync(outfile).size;
console.log(`[build-client] wrote ${path.relative(ROOT, outfile)} (${(size / 1024).toFixed(1)} KB)`);
console.log('[build-client] done. Deploy: copy the fivem-client folder into the server resources/ and add it to server.cfg.');
